"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('fourier-series-lab'))return;L.init(['harmonics','frequency'],()=>{const N=L.range('harmonics'),f=L.range('frequency'),amp=n=>4/(Math.PI*n),sum=t=>{let y=0;for(let k=0;k<N;k++){const n=2*k+1;y+=amp(n)*Math.sin(n*2*Math.PI*f*t)}return y},g=L.$('drawing');g.replaceChildren();const a=L.svg('g'),b=L.svg('g',{transform:'translate(0,280)'});g.append(a,b);L.plot(a,[{fn:t=>Math.abs(Math.sin(2*Math.PI*f*t))<1e-10?0:Math.sign(Math.sin(2*Math.PI*f*t)),color:'#172a45',dash:'6 5'},{fn:sum}],{xMax:2,yMin:-1.5,yMax:1.5,height:270,yLabel:'電壓 x（V）；虛線是目標方波'});const ax=L.plot(b,[],{xMin:0,xMax:36,yMin:0,yMax:1.4,height:270,xLabel:'正頻率（Hz）；只畫正弦成分峰值',yLabel:'正弦成分峰值（V）'});for(let k=0;k<N;k++){const n=2*k+1;b.append(L.svg('line',{x1:ax.X(n*f),y1:ax.Y(0),x2:ax.X(n*f),y2:ax.Y(amp(n)),stroke:'#cf604b','stroke-width':3}),L.svg('circle',{cx:ax.X(n*f),cy:ax.Y(amp(n)),r:4,fill:'#cf604b'}));}const ms=Array.from({length:N},(_,k)=>amp(2*k+1)**2/2).reduce((a,b)=>a+b,0);L.text('result-primary',L.fmt(sum(1/(4*f)),6)+' V');L.text('result-secondary',L.fmt(ms,6)+' V²');L.text('feedback','用了 n=1 到 '+(2*N-1)+' 的 '+N+' 個奇數諧波，第一成分峰值固定 4/π≈1.273 V。基頻 '+L.fmt(f)+' Hz → 週期 '+L.fmt(1/f)+' s；改頻率只改節奏，不改各成分幅值。t=0 的合成值為 0，是跳躍兩側 ±1 V 的平均。此處列均方值，不是無限時間總能量；多加諧波也不會完全消除跳躍附近的 Gibbs 超越。');});})();
